// DeepSeek servisini devre dışı bırakıyoruz, yerine OpenAI servisi kullanılacak
// Bu dosya uyumluluk için tutulmuştur

// OpenAI servisini import ediyoruz
import { 
  getAuraStoryFromOpenAI, 
  getAuraInsightsFromOpenAI,
  getCombinedAuraDataFromOpenAI,
  getAnswerSummary as getOpenAISummary,
  determineDynamicAuraType as determineOpenAIAuraType 
} from './openaiService';

// type tanımlarını sürdürüyoruz
interface AnswerSummary {
  answerCounts: { a: number; b: number; c: number; d: number };
  answerPattern: string;
  answerDetails: string;
  dominantTrait: string;
  secondaryTrait: string;
}

// OpenAI servisi ile aynı fonksiyonu kullanacağız
export const getAnswerSummary = (answers: { [key: number]: string }): AnswerSummary => {
  return getOpenAISummary(answers);
};

// Bu fonksiyonlar artık OpenAI servisi tarafından gerçekleştirilecek, burada sadece uyumluluk için kalacaklar
export const getAuraStoryFromDeepSeek = async (auraType: string, username: string, answers: {[key: number]: string}): Promise<string> => {
  console.warn('DeepSeek servisi devre dışı bırakıldı. OpenAI servisini kullanın.');
  // Doğrudan OpenAI servisine yönlendir
  return getAuraStoryFromOpenAI(auraType, username, answers);
};

export const getAuraInsightsFromLlama = async (auraType: string, username: string, answers: {[key: number]: string}, detailedAnswers?: any): Promise<any> => {
  console.warn('LLaMA servisi devre dışı bırakıldı. OpenAI servisini kullanın.');
  // Doğrudan OpenAI servisine yönlendir
  return getAuraInsightsFromOpenAI(auraType, username, answers, detailedAnswers);
};

export const determineDynamicAuraType = (answers: {[key: number]: string}): string => {
  // OpenAI servisi ile aynı fonksiyonu kullanıyoruz
  return determineOpenAIAuraType(answers);
};

// Prompt fonksiyonları artık JSON dosyalarındaki promptları kullanacağımız için devre dışı
export const getSystemPromptForAuraType = (auraType: string, answerDetails: string): string => {
  console.warn('Bu fonksiyon artık kullanılmıyor. JSON dosyalarındaki promptlar kullanılıyor.');
  return "";
};

export const getInsightsPromptForAuraType = (auraType: string, answerDetails: string): string => {
  console.warn('Bu fonksiyon artık kullanılmıyor. JSON dosyalarındaki promptlar kullanılıyor.');
  return "";
};

export const getCombinedAuraDataFromLlama = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<any> => {
  console.warn('LLaMA servisi devre dışı bırakıldı. OpenAI servisini kullanın.');
  // Doğrudan OpenAI servisine yönlendir
  return getCombinedAuraDataFromOpenAI(auraType, username, answers);
};
